\begin{theorem}[Thue \cite{arxivID-1308.5858-8}] \label{thue}
There exist infinitely many overlap-free binary words of length $n$ for every $n$.
\end{theorem}

In \cite{arxivID-2108.04572-9}, we have shown the following.

\begin{theorem} \label{old}
Let $w$ be an overlap-free binary word. Then $2M(w) \le |w|+3$, and there are infinitely many overlap-free binary words $w$ for which $2M(w)=|w|+3$.
\end{theorem}

In the present paper, we improve this result as follows.

\begin{theorem} \label{new}
Let $w$ be an overlap-free binary word. Then $2M(w) \le |w|+2$, and there are infinitely many overlap-free binary words $w$ for which $2M(w)=|w|+2$.
\end{theorem}

In order to prove Theorem~\ref{new}, we introduce a new parameter $T(w)$, which counts the number of positions in $w$ that are the beginning of a square. We also introduce the notion of a balanced word. We prove the following two lemmas.

\begin{lemma} \label{lem1}
Let $w$ be an overlap-free binary word. Then $2M(w)+T(w) \le |w|+4$, and there are infinitely many overlap-free binary words $w$ for which $2M(w)+T(w)=|w|+4$.
\end{lemma}

\begin{lemma} \label{lem2}
Let $w$ be an overlap-free binary word. Then $T(w) \le M(w)+2$, and there are infinitely many overlap-free binary words $w$ for which $T(w)=M(w)+2$.
\end{lemma}

From Lemmas~\ref{lem1} and~\ref{lem2} we obtain Theorem~\ref{new}. <|section_end|>

